AgentProperties.OnArrival:
if (varExploring) {
	if (varEnableSenseDebug) traceln("UAV " + getIndex() + " OnArrival explore t=" + time());
	} else if (varMovingToCharger) {
		varMovingToCharger = false;
	} else {
		// Exploit arrival handled by internal statechart
	}

Properties.EntryAction:
if (varUseAcoMove) {
	fnPickWaypoint();
	if (varEnableSenseDebug) traceln("UAV " + getIndex() + " ExplorePlan picked idx=" + varChosenIdx);
} else {
	fnMoveToRandomWaypoint();
	if (varEnableSenseDebug) traceln("UAV " + getIndex() + " ExplorePlan random move");
}

if (varUseAcoMove) {
    double tx = varCandX[varChosenIdx];
    double ty = varCandY[varChosenIdx];
    if (varEnableSenseDebug) traceln("UAV " + getIndex() + " ExploreMove entry moveTo idx=" + varChosenIdx + " target=(" + tx + "," + ty + ")");
    moveTo(tx, ty, varSpeed);
}

if (varTargetConfidence >= varDetectionThreshold) {
	setSpeed(varSpeed);
	if (varEnableSenseDebug) traceln("UAV " + getIndex() + " ExploitApproach entry target=(" + varTargetX + "," + varTargetY + ")");
	moveTo(varTargetX, varTargetY, varSpeed);
}

varExploring = false;
varMovingToCharger = true;
moveTo(880, 460, varSpeed);
varCurrentStateName = "To Charger";

varCurrentStepLength = varAcoStepLength * Math.min(varAdaptiveStepMaxMultiplier, 1.0 + varMinCandidatePheromone);
if (varEnableSenseDebug) {
    traceln(String.format("UAV %d adaptStep t=%.1f minPh=%.2f newStep=%.1f",
        getIndex(), time(), varMinCandidatePheromone, varCurrentStepLength));
}

Properties.Action:
if (varUseAcoMove) {
	double tx = varCandX[varChosenIdx];
	double ty = varCandY[varChosenIdx];
	if (varEnableSenseDebug) traceln("UAV " + getIndex() + " ExplorePlan->Move moveTo idx=" + varChosenIdx + " target=(" + tx + "," + ty + ")");
	moveTo(tx, ty, varSpeed);
}
// Random: moveTo already issued in ExplorePlan entry

varBatteryLevel = Math.max(0, varBatteryLevel - varBatteryDepletionRate * 0.25);
if (batteryText != null) {
    batteryText.setText(String.format("%.0f%%", varBatteryLevel));
}

varBatteryLevel = Math.min(100, varBatteryLevel + varChargingRate * 0.5);
if (batteryText != null) {
	batteryText.setText(String.format("%.0f%%", varBatteryLevel));
}

varLastCriticalX = getX();
varLastCriticalY = getY();
varReturnToLastLocation = true;

varLastCriticalX = getX();
varLastCriticalY = getY();
varReturnToLastLocation = true;

if (!varMovingToCharger && !varCharging) {
    varBatteryLevel = Math.max(0, varBatteryLevel - varBatteryDepletionRate * 0.5);
    if (batteryText != null) batteryText.setText(String.format("%.0f%%", varBatteryLevel));
}
